def get_total_number_of_sequences(m, n):
    """Write a function to find the number of possible sequences of length n such that each of the next element is greater than or equal to twice of the previous element but less than or equal to m."""
    if n == 0:
        return 1
    if n < 0 or m <= 0:
        return 0
    if n == 1:
        return m
    if (1 << (n - 1)) > m:
        return 0
    dp_next = [0] * (m + 2)
    for v in range(1, m + 1):
        dp_next[v] = 1
    for _ in range(n - 1):
        suffix = [0] * (m + 3)
        running = 0
        for v in range(m, 0, -1):
            running += dp_next[v]
            suffix[v] = running
        dp_cur = [0] * (m + 2)
        for v in range(1, m + 1):
            nxt = 2 * v
            if nxt <= m:
                dp_cur[v] = suffix[nxt]
            else:
                dp_cur[v] = 0
        dp_next = dp_cur
    return sum(dp_next[1:m + 1])
